// Share preparation stays local; users complete posting in their chosen app.
const shareDialog=document.createElement('dialog');shareDialog.id='share-dialog';shareDialog.setAttribute('aria-labelledby','share-heading');shareDialog.innerHTML=`<div class="dialog-head"><span>PASS THE CURIOSITY</span><button id="close-share" aria-label="关闭分享">✕</button></div><h2 id="share-heading">把这个 Slice，分享出去。</h2><div class="share-summary"><span>✳</span><div><strong id="share-title"></strong><small id="share-author"></small></div></div><div class="share-platforms" aria-label="分享平台"><button data-platform="wechat"><b class="wechat">微</b>微信 / 朋友圈</button><button data-platform="red"><b class="red">小红书</b>小红书</button><button data-platform="qq"><b class="qq">QQ</b>QQ</button><button data-platform="weibo"><b class="weibo">微</b>微博</button></div><div class="share-guide"><strong id="share-guide-title">选一个平台，准备分享</strong><p id="share-guide-text">复制链接发给朋友，或复制文案到你常用的社交平台。</p></div><label class="share-label">分享文案<textarea id="share-copy" rows="5"></textarea></label><div class="share-actions"><button id="copy-share-text">复制文案</button><button id="copy-share-link">复制链接</button><button id="native-share" class="dark">更多 / 系统分享 ↗</button></div><p id="share-feedback" role="status" aria-live="polite"></p><p class="share-footnote">平台入口提供分享指引；粘贴后由你确认发送或发布。系统分享中可选的 App 由设备决定。</p>`;document.body.append(shareDialog);
let sharedWork=null,sharedURL='';
const shareGuides={wechat:['微信 / 朋友圈','复制链接，打开微信粘贴给好友或群聊。发朋友圈可复制文案并添加自己的截图；也可以尝试系统分享中的微信入口。'],red:['分享到小红书','复制文案，打开小红书创建笔记，添加 Slice 截图或试玩录屏后粘贴。外链是否可点击以平台展示为准。'],qq:['分享到 QQ','复制链接，打开 QQ 选择好友或群聊后粘贴发送。手机上也可以尝试系统分享。'],weibo:['分享到微博','复制文案，打开微博创建新动态，粘贴后按需添加截图，再确认发布。']};
function openSliceShare(id){const w=works.find(x=>x.id===id);if(!w)return;sharedWork=w;const url=new URL(location.pathname,location.origin);url.hash='work='+encodeURIComponent(w.id);sharedURL=w.local?'':url.href;document.querySelector('#share-title').textContent=w.title;document.querySelector('#share-author').textContent=w.author+' · '+w.cat;document.querySelector('#share-copy').value=`${w.title}\n\n${w.desc}\n\n来自 ${w.author} 的 Slice${sharedURL?'\n亲手试一下：'+sharedURL:'\n（本机创作，尚未公开）'}\n#Slice #互动内容`;document.querySelector('#copy-share-link').disabled=!sharedURL;document.querySelector('#native-share').disabled=!navigator.share;document.querySelector('#share-guide-title').textContent=w.local?'这个 Slice 还只保存在本机':'选一个平台，准备分享';document.querySelector('#share-guide-text').textContent=w.local?'可以复制文案，但暂时没有其他人可打开的链接。':'复制链接发给朋友，或复制文案到你常用的社交平台。';document.querySelector('#share-feedback').textContent=navigator.share?'':'此浏览器暂不支持系统分享，可使用复制文案或链接。';shareDialog.querySelectorAll('[data-platform]').forEach(b=>b.setAttribute('aria-pressed','false'));shareDialog.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-share]');if(b){e.preventDefault();e.stopImmediatePropagation();openSliceShare(b.dataset.share)}},true);
shareDialog.querySelectorAll('[data-platform]').forEach(b=>b.onclick=()=>{shareDialog.querySelectorAll('[data-platform]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const guide=shareGuides[b.dataset.platform];document.querySelector('#share-guide-title').textContent=guide[0];document.querySelector('#share-guide-text').textContent=guide[1]+(sharedURL?'':' 此 Slice 尚无公开链接，可先分享文案。')});
async function copySliceShare(linkOnly){const field=document.querySelector('#share-copy'),value=linkOnly?sharedURL:field.value;if(!value)return;try{await navigator.clipboard.writeText(value);document.querySelector('#share-feedback').textContent=(linkOnly?'链接':'文案')+'已复制，请到所选平台粘贴。'}catch{field.value=value;field.focus();field.select();document.querySelector('#share-feedback').textContent='自动复制未获允许，已选中文字，请手动复制。'}}
document.querySelector('#copy-share-text').onclick=()=>copySliceShare(false);document.querySelector('#copy-share-link').onclick=()=>copySliceShare(true);document.querySelector('#native-share').onclick=async()=>{try{await navigator.share({title:sharedWork.title,text:document.querySelector('#share-copy').value});document.querySelector('#share-feedback').textContent='已交给系统分享。'}catch(e){document.querySelector('#share-feedback').textContent=e.name==='AbortError'?'已取消分享。':'系统分享暂不可用，请复制文案或链接。'}};document.querySelector('#close-share').onclick=()=>shareDialog.close();shareDialog.addEventListener('click',e=>{if(e.target===shareDialog){const r=shareDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)shareDialog.close()}});
const detailShare=document.createElement('button');detailShare.textContent='↗ Share';detailShare.onclick=()=>openSliceShare(activeId);document.querySelector('.dialog-bottom').prepend(detailShare);
